tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-families-offer-free-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e bench/variations/stage7-3c-families-offer.json -e tests/test_3c_families_offer.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame data || { echo "FAIL: storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_3c_families_offer.py tests/test_3c_cue_chain.py tests/test_3c_cue_wording.py tests/test_resolution_cascade.py tests/test_markdown_story_package.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
$PY -m ruff check tests/test_3c_families_offer.py && $PY -m ruff format --check tests/test_3c_families_offer.py || exit 1
git add -A -- tests bench/variations && git diff --cached -- tests bench/variations > /home/bcorfman/dev/ringer-work/3c-families-offer-free.patch && test -s /home/bcorfman/dev/ringer-work/3c-families-offer-free.patch && echo "patch exported
